# Local-only secret consolidation
#
# This script reads the existing local secret-bearing files and writes
# gitignored env files for the controller, data platform and liquidation bot.
# It prints only paths and key counts, never values.
#
# Run from anywhere:
#   powershell -ExecutionPolicy Bypass -File Suban/scripts/sync-local-env.ps1
#
# The generated files are intentionally ignored by git:
#   Suban/.env.local
#   Suban/deploy/.env.local
#   Suban/services/event-indexer/.env.local
#   Suban/services/liquidation-bot/.env.local
#   suban-controller/.env.local
#
# Do not add real values to any tracked file.

$ErrorActionPreference = 'Stop'

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$subanRoot = Split-Path -Parent $scriptDir
$workspaceRoot = Split-Path -Parent $subanRoot
$controllerRoot = Join-Path $workspaceRoot 'suban-controller'

function Read-EnvFile {
  param([string]$Path)
  $map = [ordered]@{}
  if (-not (Test-Path -LiteralPath $Path)) { return $map }
  foreach ($line in Get-Content -LiteralPath $Path) {
    $trimmed = $line.Trim()
    if (-not $trimmed -or $trimmed.StartsWith('#')) { continue }
    $index = $trimmed.IndexOf('=')
    if ($index -lt 1) { continue }
    $key = $trimmed.Substring(0, $index).Trim()
    $value = $trimmed.Substring($index + 1).Trim()
    if ($value.Length -ge 2) {
      $first = $value.Substring(0, 1)
      $last = $value.Substring($value.Length - 1, 1)
      if (($first -eq '"' -and $last -eq '"') -or ($first -eq "'" -and $last -eq "'")) {
        $value = $value.Substring(1, $value.Length - 2)
      }
    }
    $map[$key] = $value
  }
  return $map
}

function Read-TomlValue {
  param([string]$Path, [string]$Key)
  if (-not (Test-Path -LiteralPath $Path)) { return '' }
  foreach ($line in Get-Content -LiteralPath $Path) {
    if ($line -match "^\s*$([regex]::Escape($Key))\s*=\s*`"(.*)`"\s*$") {
      return $matches[1]
    }
  }
  return ''
}

function New-HexSecret {
  $bytes = New-Object byte[] 32
  $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
  try {
    $rng.GetBytes($bytes)
  } finally {
    $rng.Dispose()
  }
  return (($bytes | ForEach-Object { $_.ToString('x2') }) -join '')
}

function Write-LocalEnv {
  param([string]$Path, [string[]]$Lines)
  $directory = Split-Path -Parent $Path
  if (-not (Test-Path -LiteralPath $directory)) {
    New-Item -ItemType Directory -Path $directory | Out-Null
  }
  [System.IO.File]::WriteAllText($Path, (($Lines -join "`n") + "`n"), [System.Text.UTF8Encoding]::new($false))
  $count = ($Lines | Where-Object { $_ -match '^[A-Za-z_][A-Za-z0-9_]*=' }).Count
  Write-Output "Wrote $Path ($count keys)"
}

function Assert-Ignored {
  param([string]$Repo, [string]$Path)
  & git -C $Repo check-ignore -q -- $Path
  if ($LASTEXITCODE -ne 0) {
    throw "Refusing to write a non-ignored file: $Path"
  }
}

